static constexpr int s_nHatModelCount = 9461;

// Binary search for model path by def index
inline const HatModelEntry_t* FindHatModel(int nDefIndex)
{
	int lo = 0, hi = s_nHatModelCount - 1;
	while (lo <= hi)
	{
		int mid = (lo + hi) / 2;
		if (s_HatModels[mid].nDefIndex == nDefIndex)
			return &s_HatModels[mid];
		if (s_HatModels[mid].nDefIndex < nDefIndex)
			lo = mid + 1;
		else
			hi = mid - 1;
	}
	return nullptr;
}
